const $ = (s, root = document) => root.querySelector(s);
const state = {account:null, smsAvailable:false, authPage:'login', authBusy:false, authNotice:'', resetChallenge:null, authVersion:0, items: [], orders: [], lines: [], page: 'overview', category: 'All items', search: '', cart: new Map(), reportDays: 7, chartDays: 7, inventorySearch: '', busy: false, pending: null};
const paths = {logout:'M9 4H4v16h5m5-13 5 5-5 5m-7-5h12',eye:'M2 12s3-7 10-7 10 7 10 7-3 7-10 7S2 12 2 12Zm13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',lock:'M6 10h12v11H6V10Zm3 0V6a3 3 0 0 1 6 0v4m-3 4v3',phone:'M8 2h8v20H8V2Zm0 15h8m-4 2v.01',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',bag:'M5 7h14l1 14H4L5 7ZM9 8V6a3 3 0 0 1 6 0v2',box:'m3 7 9-4 9 4-9 4-9-4Zm0 0v10l9 4 9-4V7M12 11v10M7 5l10 4',chart:'M4 3v18h17M8 16v-4m5 4V8m5 8V5',book:'M4 3h12a3 3 0 0 1 3 3v15H6a3 3 0 0 1-3-3V6a3 3 0 0 1 3-3Zm0 14h15M8 7h7M8 11h5',info:'M12 11v6m0-10v.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',menu:'M4 6h16M4 12h16M4 18h16',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',down:'m7 10 5 5 5-5',up:'m4 16 6-6 4 4 6-8m-6 0h6v6',wallet:'M4 6V4h14v4M3 8h18v12H3V8Zm13 5h5m-5 3h.01',receipt:'M5 3h14v18l-3-2-4 2-4-2-3 2V3Zm4 4h6M9 11h6M9 15h3',utensils:'M4 3v6a3 3 0 0 0 6 0V3M7 3v18M18 3c-3 4-3 9 0 9h2V3h-2Zm2 9v9',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',search:'m21 21-5-5M18 10A8 8 0 1 1 2 10a8 8 0 0 1 16 0Z',close:'m6 6 12 12M6 18 18 6',minus:'M5 12h14',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',check:'m5 12 4 4L19 6',download:'M12 3v12m-5-5 5 5 5-5M5 16v5h14v-5',edit:'m16 3 5 5-12 12H4v-5L16 3Zm-2 2 5 5',alert:'m12 3 10 18H2L12 3Zm0 6v5m0 3v.01',leaf:'M20 3c-9-1-16 3-16 10a7 7 0 0 0 7 7c7 0 10-8 9-17ZM5 20 16 9',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z',calendar:'M4 5h16v16H4V5Zm0 5h16M8 3v4m8-4v4',print:'M7 8V3h10v5M7 17H3V8h18v9h-4M7 13h10v8H7v-8ZM17 11h.01',code:'m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18',database:'M20 6c0 2-4 3-8 3S4 8 4 6s4-3 8-3 8 1 8 3ZM4 6v12c0 2 4 3 8 3s8-1 8-3V6M4 12c0 2 4 3 8 3s8-1 8-3',refresh:'M20 7v5h-5M4 17v-5h5M6 6a8 8 0 0 1 13 3M5 15a8 8 0 0 0 13 3'};
const icon = (name, cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.bag}"/></svg>`;
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = v => new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:Number(v)%100?2:0}).format(Number(v || 0)/100);
const number = v => new Intl.NumberFormat('en-IN').format(v || 0);
const dateKey = v => new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(v));
const today = () => dateKey(new Date());
const dateAgo = n => dateKey(new Date(Date.now()-n*86400000));
const time = v => new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',hour:'numeric',minute:'2-digit'}).format(new Date(v));
const shortDate = v => new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',day:'numeric',month:'short'}).format(new Date(v));
const sum = (a,key) => a.reduce((n,r)=>n+Number(r[key]||0),0);
const activeItems = () => state.items.filter(i=>i.active !== 0);
const inRange = (rows, days) => rows.filter(r=>dateKey(r.created_at)>=dateAgo(days-1) && dateKey(r.created_at)<=today());
const photoMap = {dosa:'photo-1668236543090-82eba5ee5976',idli:'photo-1589301760014-d929f3979dbc',samosa:'photo-1601050690597-df0568f70950',sandwich:'photo-1528735602780-2552fd46c7af',tea:'photo-1544787219-7f47ccb76574',coffee:'photo-1509042239860-f550ce710b93',biryani:'photo-1563379091339-03246963d51a',rice:'photo-1516684732162-798a0062be99',juice:'photo-1600271886742-f049cd451bba',vada:'photo-1630383249896-424e482df921',noodles:'photo-1512058564366-18510be2db19',chai:'photo-1544787219-7f47ccb76574',wrap:'photo-1626700051175-6818013e1d4f',thali:'photo-1546833999-b9f581a1996d',lime:'photo-1513558161293-cdaf765edfd7',poha:'photo-1516684732162-798a0062be99',dessert:'photo-1589119908995-c6837fa14848',meals:'photo-1546833999-b9f581a1996d'};
function foodPhoto(item) { const supplied = String(item?.image || ''); if (/^https:\/\/images\.unsplash\.com\//.test(supplied)) return supplied; const key = Object.keys(photoMap).find(k=>(supplied+' '+item?.name).toLowerCase().includes(k)) || 'meals'; return `https://images.unsplash.com/${photoMap[key]}?auto=format&fit=crop&w=480&q=80`; }
const thumb = (item, cls='food-thumb') => `<img class="${cls}" src="${esc(foodPhoto(item))}" alt="" loading="lazy" onerror="this.style.visibility='hidden'">`;
async function api(path, options={}) {
  const requestVersion=state.authVersion,protectedRequest=!path.startsWith('/auth/');
  const response=await fetch('/api'+path,{...options,credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json',...options.headers}});
  if(protectedRequest&&requestVersion!==state.authVersion){const error=new Error('Your session changed. Please try again.');error.status=401;error.silent=true;throw error;}
  let result;try{result=await response.json();}catch{throw new Error('The server returned an unexpected response. Please try again.');}
  if(protectedRequest&&requestVersion!==state.authVersion){const error=new Error('Your session changed. Please try again.');error.status=401;error.silent=true;throw error;}
  if(!response.ok){const error=new Error(result.error||'Something went wrong. Please try again.');error.status=response.status;if(response.status===401&&protectedRequest){clearAccount();state.authNotice='Your session has ended. Please sign in again.';renderAuth();}throw error;}
  return result;
}
async function refresh() { const authVersion=state.authVersion; const [menu,orders,sales]=await Promise.all([api('/menu'),api('/orders'),api('/sales')]); if(!state.account||authVersion!==state.authVersion){const error=new Error('Your session has ended. Please sign in again.');error.status=401;throw error;} state.items=menu.items; state.orders=orders.orders; state.lines=sales.lines; const low=activeItems().filter(i=>i.stock<=10).length; $('#low-stock-nav').textContent=low; $('#low-stock-nav').hidden=!low; }
function toast(message,error=false) { const t=$('#toast');t.innerHTML=icon(error?'alert':'check')+`<span>${esc(message)}</span>`; t.className='toast visible'+(error?' toast-error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),4200); }
function heading(eyebrow,title,subtitle,actions='') { return `<div class="page-heading"><div class="heading-copy"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`; }
const newOrderBtn = () => `<a class="btn btn-primary" href="#order">${icon('plus')} New order</a>`;
function trend(value,previous) { if (!previous) return `<span class="muted">${value?'First sales for this period':'No sales yet'}</span>`; const diff=(value-previous)/previous*100; return `<span class="trend ${diff<0?'negative':''}">${diff<0?'↘':'↗'} ${Math.abs(diff).toFixed(1)}%</span><span class="muted">vs. yesterday</span>`; }
function metric(label,value,symbol,foot,color='green') { return `<article class="metric-card"><div class="metric-top"><span>${label}</span><span class="metric-icon ${color}">${icon(symbol)}</span></div><div class="metric-value">${value}</div><div class="metric-bottom">${foot}</div></article>`; }
function revenueChart(days, expanded=false) { const orders=inRange(state.orders,days); const buckets=Array.from({length:days},(_,i)=>{const day=dateAgo(days-1-i);return {day,value:sum(orders.filter(o=>dateKey(o.created_at)===day),'total_paise')};}); const max=Math.max(...buckets.map(b=>b.value),10000); const nice=Math.ceil(max/40000)*40000; const W=660,H=210,left=44,right=10,top=16,bottom=35,iw=W-left-right,ih=H-top-bottom; const pts=buckets.map((b,i)=>[left+i*iw/Math.max(days-1,1),top+ih-(b.value/nice)*ih]); const poly=pts.map(p=>p.join(',')).join(' '); const area=`${left},${H-bottom} ${poly} ${W-right},${H-bottom}`; let svg=`<svg class="chart-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="Daily revenue over ${days} days: ${esc(buckets.map(b=>shortDate(b.day)+' '+money(b.value)).join('; '))}"><defs><linearGradient id="revenue-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#6ca98a" stop-opacity=".22"/><stop offset="100%" stop-color="#6ca98a" stop-opacity=".02"/></linearGradient></defs>`; for(let i=0;i<=4;i++){let y=top+i*ih/4;let val=nice*(4-i)/4;svg+=`<line x1="${left}" y1="${y}" x2="${W-right}" y2="${y}" stroke="#e9ede7" stroke-dasharray="4 4"/><text x="${left-10}" y="${y+4}" text-anchor="end" fill="#94a097" font-size="10">${val>=100000?'₹'+(val/100000).toFixed(val%100000?1:0)+'k':'₹'+Math.round(val/100)}</text>`;} svg+=`<polygon points="${area}" fill="url(#revenue-fill)"/><polyline points="${poly}" fill="none" stroke="#39775a" stroke-width="2.8" stroke-linejoin="round" stroke-linecap="round"/>`;buckets.forEach((b,i)=>{if(days<=7||i%Math.ceil(days/7)===0||i===days-1)svg+=`<text x="${pts[i][0]}" y="${H-10}" text-anchor="middle" fill="#8b988e" font-size="10">${days===7?new Intl.DateTimeFormat('en',{weekday:'short',timeZone:'Asia/Kolkata'}).format(new Date(b.day)):shortDate(b.day)}</text>`;svg+=`<circle cx="${pts[i][0]}" cy="${pts[i][1]}" r="4" fill="#fff" stroke="#39775a" stroke-width="2"><title>${shortDate(b.day)}: ${money(b.value)}</title></circle>`;}); return `<div class="chart-total">${money(sum(orders,'total_paise'))}<span>total revenue</span></div><div class="chart-wrap">${svg}</svg></div><div class="chart-caption"><span class="chart-legend"><i></i>Revenue</span><span>${shortDate(dateAgo(days-1))} – ${shortDate(today())} · IST</span></div>`; }
function popularRows(days,limit=4) { const grouped=new Map();inRange(state.lines,days).forEach(l=>{const prev=grouped.get(l.item_id)||{id:l.item_id,name:l.item_name,quantity:0,revenue:0};prev.quantity+=Number(l.quantity);prev.revenue+=Number(l.line_total_paise);grouped.set(l.item_id,prev);});return [...grouped.values()].sort((a,b)=>b.quantity-a.quantity||b.revenue-a.revenue).slice(0,limit); }
function popularPanel(days,limit=4) { const rows=popularRows(days,limit); const max=rows[0]?.quantity||1;return rows.length?`<div class="popular-list">${rows.map((r,i)=>`<div class="popular-item"><span class="rank">${String(i+1).padStart(2,'0')}</span>${thumb(state.items.find(m=>m.id===r.id)||r)}<div class="popular-copy"><div class="popular-line"><span class="popular-name">${esc(r.name)}</span><span class="popular-price">${money(r.revenue)}</span></div><div class="popular-meta">${number(r.quantity)} sold<span>${Math.round(r.quantity/max*100)}%</span></div><div class="progress-track"><div class="progress-bar" style="width:${r.quantity/max*100}%"></div></div></div></div>`).join('')}</div>`:empty('No favourites yet','Your bestselling items will appear after the first order.','utensils'); }
function orderTable(orders,limit=6) { return orders.length?`<div class="table-wrap"><table><thead><tr><th>ORDER</th><th>CUSTOMER</th><th>ITEMS</th><th>AMOUNT</th><th>STATUS</th></tr></thead><tbody>${orders.slice(0,limit).map(o=>`<tr data-action="receipt" data-id="${esc(o.id)}" tabindex="0" role="button" aria-label="View order for ${esc(o.customer_name)}"><td><strong class="order-id">#${esc(o.id.slice(-6).toUpperCase())}</strong><span class="cell-sub">${dateKey(o.created_at)===today()?time(o.created_at):shortDate(o.created_at)+' · '+time(o.created_at)}</span></td><td><span class="order-customer"><span class="customer-dot">${esc(o.customer_name.slice(0,1).toUpperCase())}</span>${esc(o.customer_name)}</span></td><td>${sum(o.items||[],'quantity')} <span class="muted">items</span></td><td class="amount-cell">${money(o.total_paise)}</td><td><span class="status-badge">${icon('check')}Completed</span></td></tr>`).join('')}</tbody></table></div>`:empty('Your first order is waiting','Completed orders and receipts will appear here.','receipt'); }
function empty(title,description,symbol='bag') {return `<div class="empty-state"><span>${icon(symbol)}</span><h3>${title}</h3><p>${description}</p></div>`;}
function overview(){const td=state.orders.filter(o=>dateKey(o.created_at)===today()),yd=state.orders.filter(o=>dateKey(o.created_at)===dateAgo(1));const revenue=sum(td,'total_paise'), yesterday=sum(yd,'total_paise');const tdLines=state.lines.filter(l=>dateKey(l.created_at)===today());const low=activeItems().filter(i=>i.stock<=10).sort((a,b)=>a.stock-b.stock);return heading('THE DAILY DISH','Your canteen, at a glance.',"A little clarity for a busy day. Here’s how your kitchen is doing.",`<span class="today-label">${icon('calendar')} Today</span>${newOrderBtn()}`)+`<div class="metric-grid">${metric("Today's revenue",money(revenue),'wallet',trend(revenue,yesterday))}${metric('Orders served',number(td.length),'receipt',trend(td.length,yd.length),'orange')}${metric('Average order',money(td.length?Math.round(revenue/td.length):0),'bag','<span class="muted">A little of everything, on average</span>','blue')}${metric('Items sold',number(sum(tdLines,'quantity')),'utensils',`<span class="muted">Across ${new Set(tdLines.map(l=>l.item_id)).size} menu favourites</span>`,'purple')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-heading"><div><h2>Revenue overview</h2><p class="panel-subtitle">Every order adds up.</p></div><select id="chart-days" class="compact-select" aria-label="Revenue period"><option value="7" ${state.chartDays===7?'selected':''}>Last 7 days</option><option value="30" ${state.chartDays===30?'selected':''}>Last 30 days</option></select></div>${revenueChart(state.chartDays)}</section><section class="panel popular-panel"><div class="panel-heading"><div><h2>Campus favourites <span class="tiny-leaf">${icon('leaf')}</span></h2><p class="panel-subtitle">The most-loved bites this week.</p></div><a href="#reports" class="icon-btn" aria-label="View item sales">${icon('arrow')}</a></div>${popularPanel(7)}</section></div><div class="bottom-grid"><section class="panel orders-panel"><div class="panel-heading"><div><h2>Recent orders <span class="count-tag">${number(state.orders.length)}</span></h2><p class="panel-subtitle">Fresh from the counter.</p></div><a href="#reports" class="text-link">View all ${icon('arrow')}</a></div>${orderTable(state.orders,5)}</section><section class="panel stock-panel"><div class="panel-heading"><div><h2>Stock watch <span class="stock-dot"></span></h2><p class="panel-subtitle">A quick check before the next rush.</p></div></div>${low.length?`<div class="stock-list">${low.slice(0,4).map(i=>`<div class="stock-item"><span class="stock-icon">${icon(i.stock?'box':'alert')}</span><div class="stock-copy"><strong>${esc(i.name)}</strong><span>${i.stock?'Running low':'Time to restock'}</span></div><span class="stock-count ${i.stock?'':'out'}">${i.stock} left</span><button class="icon-btn" data-action="edit-item" data-id="${i.id}" aria-label="Restock ${esc(i.name)}">${icon('plus')}</button></div>`).join('')}</div><a class="stock-alert" href="#inventory">${icon('alert')} ${low.length} ${low.length===1?'item needs':'items need'} a little attention ${icon('arrow')}</a>`:empty('Everything is well stocked','You’re ready for the next campus rush.','check')}</section></div><div class="feature-banner"><span class="banner-icon">${icon('spark')}</span><div class="banner-copy"><strong>A smoother rush starts with a little insight.</strong><p>Find your bestsellers, spot busy days, and make every plate count.</p></div><a class="banner-link" href="#reports">Explore sales reports ${icon('arrow')}</a></div>`;}
function orderPage(){const cats=['All items',...new Set(activeItems().map(i=>i.category))];const items=activeItems().filter(i=>(state.category==='All items'||i.category===state.category)&&`${i.name} ${i.description}`.toLowerCase().includes(state.search.toLowerCase()));return heading('AT THE COUNTER','What’s cooking?','Good food, one order at a time. Pick the favourites and we’ll do the maths.',`<span class="availability-pill"><i></i>${activeItems().filter(i=>i.stock>0).length} items available</span>`)+`<div class="order-layout"><section><div class="toolbar"><label class="search-field">${icon('search')}<input id="menu-search" type="search" placeholder="Search the menu…" value="${esc(state.search)}" aria-label="Search menu"></label><span class="muted menu-count">${items.length} items</span></div><div class="filter-chips">${cats.map(c=>`<button class="chip ${c===state.category?'active':''}" data-action="category" data-category="${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="menu-grid">${items.map(i=>`<article class="food-card ${i.stock?'':'sold-out'}"><div class="food-image">${thumb(i,'')}<span class="food-category">${esc(i.category)}</span>${i.stock<=10?`<span class="food-stock">${i.stock?i.stock+' left':'Sold out'}</span>`:''}</div><div class="food-card-body"><h2 class="food-title">${esc(i.name)}</h2><p class="food-description">${esc(i.description||'Freshly prepared in the campus kitchen.')}</p><div class="food-bottom"><span class="food-price">${money(i.price_paise)}</span><button class="add-btn" data-action="add-cart" data-id="${i.id}" ${!i.stock||Number(state.cart.get(i.id)||0)>=i.stock?'disabled':''} aria-label="Add ${esc(i.name)} to order">${icon('plus')} Add${state.cart.get(i.id)?` (${state.cart.get(i.id)})`:''}</button></div></div></article>`).join('')}</div>${!items.length?empty('No bites found','Try another search or choose a different category.','search'):''}</section><aside class="panel cart-panel" aria-label="Current order">${cartContent()}</aside></div>`;}
function cartContent(){const items=[...state.cart].map(([id,quantity])=>({...state.items.find(i=>i.id===id),quantity}));const total=items.reduce((n,i)=>n+i.price_paise*i.quantity,0);return `<div class="panel-heading"><div><h2>Current order <span class="count-tag">${sum(items,'quantity')}</span></h2><p class="panel-subtitle">A plate full of good choices.</p></div>${items.length?`<button class="icon-btn" data-action="clear-cart" aria-label="Clear current order">${icon('trash')}</button>`:''}</div>${items.length?`<div class="cart-list">${items.map(i=>`<div class="cart-item">${thumb(i)}<div class="cart-item-copy"><strong class="cart-item-title">${esc(i.name)}</strong><span class="cart-item-price">${money(i.price_paise)}</span></div><div class="quantity-control"><button data-action="minus-cart" data-id="${i.id}" aria-label="Remove one ${esc(i.name)}">${icon('minus')}</button><span>${i.quantity}</span><button data-action="add-cart" data-id="${i.id}" ${i.quantity>=i.stock?'disabled':''} aria-label="Add one ${esc(i.name)}">${icon('plus')}</button></div></div>`).join('')}</div>`:`<div class="cart-empty">${icon('bag')}<h3>Something delicious awaits</h3><p>Add an item from the menu<br>to start a new order.</p></div>`}<div class="cart-summary"><div class="summary-row"><span>Subtotal</span><strong>${money(total)}</strong></div><div class="summary-row"><span>Additional charges</span><span>₹0</span></div><div class="summary-total"><span>Total</span><strong>${money(total)}</strong></div><button class="btn btn-primary checkout-btn" data-action="checkout" ${items.length?'':'disabled'}>Continue to checkout ${icon('arrow')}</button><p class="cart-footnote">${icon('check')} Stock updates when your order is complete</p></div>`;}
function inventoryPage(){const items=state.items.filter(i=>`${i.name} ${i.category}`.toLowerCase().includes(state.inventorySearch.toLowerCase()));return heading('KITCHEN ESSENTIALS','A menu in good order.','Keep prices fresh and shelves ready for the next hungry student.',`<button class="btn btn-primary" data-action="new-item">${icon('plus')} Add menu item</button>`)+`<div class="inventory-summary"><span><strong>${activeItems().length}</strong> active items</span><span><i class="status-dot"></i>${activeItems().filter(i=>i.stock>10).length} well stocked</span><span><i class="status-dot amber"></i>${activeItems().filter(i=>i.stock>0&&i.stock<=10).length} running low</span><span><i class="status-dot red"></i>${activeItems().filter(i=>!i.stock).length} out of stock</span></div><section class="panel inventory-panel"><div class="toolbar"><label class="search-field">${icon('search')}<input type="search" id="inventory-search" placeholder="Find an item…" aria-label="Search inventory" value="${esc(state.inventorySearch)}"></label><span class="muted">${items.length} menu items</span></div><div class="table-wrap"><table class="inventory-table"><thead><tr><th>MENU ITEM</th><th>CATEGORY</th><th>PRICE</th><th>AVAILABLE STOCK</th><th>STATUS</th><th></th></tr></thead><tbody>${items.map(i=>`<tr><td><div class="item-cell">${thumb(i)}<div class="item-details"><strong>${esc(i.name)}</strong><span>${esc(i.description)}</span></div></div></td><td>${esc(i.category)}</td><td class="amount-cell">${money(i.price_paise)}</td><td><strong>${i.stock}</strong><span class="muted"> units</span></td><td><span class="status-badge ${!i.active?'inactive':!i.stock?'out':i.stock<=10?'low':''}">${!i.active?'Archived':!i.stock?'Out of stock':i.stock<=10?'Low stock':'In stock'}</span></td><td><button class="btn btn-secondary btn-sm" data-action="edit-item" data-id="${i.id}">${icon('edit')} Edit</button></td></tr>`).join('')}</tbody></table></div>${!items.length?empty('No menu items found','Add a new item or try another search.','search'):''}</section>`;}
function reportsPage(){const days=state.reportDays,orders=inRange(state.orders,days),lines=inRange(state.lines,days),popular=popularRows(days,8);return heading('A LITTLE FOOD FOR THOUGHT','Every order tells a story.','Turn your daily sales into a clearer picture of what your campus loves.',`<select id="report-days" class="compact-select" aria-label="Report period"><option value="7" ${days===7?'selected':''}>Last 7 days</option><option value="30" ${days===30?'selected':''}>Last 30 days</option><option value="90" ${days===90?'selected':''}>Last 90 days</option></select><button class="btn btn-primary" data-action="export">${icon('download')} Export CSV</button>`)+`<div class="report-range">${icon('calendar')} ${shortDate(dateAgo(days-1))} – ${shortDate(today())} <span>· All dates in India Standard Time</span></div><div class="metric-grid">${metric('Total revenue',money(sum(orders,'total_paise')),'wallet',`<span class="muted">Across the last ${days} days</span>`)}${metric('Completed orders',number(orders.length),'receipt','<span class="muted">Paid and ready to enjoy</span>','orange')}${metric('Items sold',number(sum(lines,'quantity')),'utensils',`<span class="muted">${new Set(lines.map(l=>l.item_id)).size} different menu items</span>`,'blue')}${metric('Most popular',esc(popular[0]?.name||'—'),'leaf',`<span class="muted">${popular[0]?number(popular[0].quantity)+' portions sold':'Complete an order to get started'}</span>`)}</div><div class="dashboard-grid"><section class="panel"><div class="panel-heading"><div><h2>Daily revenue</h2><p class="panel-subtitle">See the rhythm of your kitchen.</p></div></div>${revenueChart(days)}</section><section class="panel"><div class="panel-heading"><div><h2>Popular food items</h2><p class="panel-subtitle">Ranked by portions sold.</p></div></div>${popularPanel(days,5)}</section></div><section class="panel report-items"><div class="panel-heading"><div><h2>Item-wise sales</h2><p class="panel-subtitle">A closer look at what’s leaving the kitchen.</p></div></div><div class="table-wrap"><table><thead><tr><th>FOOD ITEM</th><th>QUANTITY SOLD</th><th>REVENUE</th><th>SHARE OF REVENUE</th></tr></thead><tbody>${popularRows(days,1000).map(r=>`<tr><td><strong>${esc(r.name)}</strong></td><td>${number(r.quantity)}</td><td class="amount-cell">${money(r.revenue)}</td><td><div class="share-cell"><div class="progress-track"><div class="progress-bar" style="width:${r.revenue/Math.max(sum(orders,'total_paise'),1)*100}%"></div></div><span>${(r.revenue/Math.max(sum(orders,'total_paise'),1)*100).toFixed(1)}%</span></div></td></tr>`).join('')}</tbody></table></div>${!lines.length?empty('No sales in this period','Try a longer date range or complete a new order.','chart'):''}</section><section class="panel report-orders"><div class="panel-heading"><div><h2>Transaction history</h2><p class="panel-subtitle">${orders.length} completed ${orders.length===1?'order':'orders'} in this period. Select an order for its receipt.</p></div></div>${orderTable(orders,1000)}</section>`;}
function docsPage(){return heading('BUILT TO BE UNDERSTOOD','From counter to coursework.','Your complete College Canteen Ordering and Sales Analysis project, ready to explore.',`<a href="/submission.zip" class="btn btn-primary" download>${icon('download')} Download project</a>`)+`<div class="project-intro"><span class="project-scenario">SCENARIO 03</span><h2>College Canteen Ordering<br>and Sales Analysis System</h2><p>A complete project that connects menu management, stock-safe ordering, transaction storage, and meaningful sales analysis.</p><div class="tech-tags"><span>Java</span><span>SQLite / SQL</span><span>Python</span><span>HTML · CSS · JavaScript</span></div><p class="register-note">For Register Nos. 3, 33, 63 & 93</p></div><div class="docs-grid">${[['book','Requirements & design','Software Requirements Specification, architecture and design diagrams, test plan, and testing evidence.','docs/'],['code','Java application','Runnable Java backend with database transactions, stock validation, sample inputs, and outputs.','java/'],['database','Database design','ER diagram, relational model, SQL schema and seed data, plus normalization details.','database/'],['chart','Python analysis','Database retrieval, preprocessing, item sales, daily revenue, and popular food visualizations.','analysis/']].map(([i,title,copy,path])=>`<article class="doc-card"><span class="doc-icon">${icon(i)}</span><h3>${title}</h3><p>${copy}</p><code>${path}</code></article>`).join('')}</div><section class="panel docs-instructions"><h2>Make it your submission</h2><ol><li><strong>Download the project.</strong> The ZIP includes the source, documentation, sample data, and execution instructions.</li><li><strong>Run it locally.</strong> Follow README.md to start the Java application and generate the Python analysis.</li><li><strong>Make it yours.</strong> Add your name and register number, review the documents, and upload to your individual GitHub repository.</li></ol><div class="docs-note">${icon('info')} The hosted edition uses a cloud Worker and a persistent SQL database. The submission includes a Java + SQLite edition with the same menu, ordering, and reporting API.</div></section>`;}
function render(){if(!state.account){renderAuth();return;}const page=location.hash.slice(1)||'overview';state.page=['overview','order','inventory','reports','docs'].includes(page)?page:'overview';const labels={overview:'Overview',order:'New order',inventory:'Menu & stock',reports:'Sales reports',docs:'Project docs'};document.title=`${labels[state.page]} — virudhigakv`;$('#breadcrumb-current').textContent=labels[state.page];document.querySelectorAll('[data-nav]').forEach(n=>{n.classList.toggle('active',n.dataset.nav===state.page);if(n.dataset.nav===state.page)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});$('#main-content').innerHTML=({overview,order:orderPage,inventory:inventoryPage,reports:reportsPage,docs:docsPage}[state.page])();}
function openModal(html){$('#modal-content').innerHTML=html;$('#modal').showModal();const focus=$('input,select,button,a', $('#modal-content'));if(focus)focus.focus();}
function modalHeader(title,sub=''){return `<div class="modal-header"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>`;}
function checkout(){if(!state.cart.size)return;openModal(modalHeader('One last thing…','A few details, then it’s over to the kitchen.')+`<form id="checkout-form"><div class="modal-body"><label class="field">Customer name<input name="customer_name" maxlength="80" placeholder="Walk-in customer" autocomplete="off"></label><div class="field-row"><label class="field">Order type<select name="order_type"><option>Dine-in</option><option>Takeaway</option></select></label><label class="field">Payment method<select name="payment_method"><option>Cash</option><option>UPI</option><option>Card</option></select></label></div><div class="checkout-lines">${[...state.cart].map(([id,q])=>{const i=state.items.find(i=>i.id===id);return `<div class="summary-row"><span>${esc(i.name)} <span class="muted">× ${q}</span></span><strong>${money(i.price_paise*q)}</strong></div>`;}).join('')}</div><div class="summary-total"><span>Total to collect</span><strong>${money([...state.cart].reduce((n,[id,q])=>n+state.items.find(i=>i.id===id).price_paise*q,0))}</strong></div><p class="form-note">Confirm after collecting payment. Stock will be updated automatically.</p><p class="form-error" id="checkout-error" role="alert"></p></div><div class="modal-footer"><button type="button" class="btn btn-secondary" data-action="close-modal">Go back</button><button class="btn btn-primary" type="submit">${icon('check')} Complete order</button></div></form>`);}
function itemForm(id){const item=state.items.find(i=>i.id===Number(id));openModal(modalHeader(item?'Keep it fresh.':'A new campus favourite.',item?'Update this item’s details and available stock.':'Add something delicious to your menu.')+`<form id="item-form" data-id="${item?.id||''}"><div class="modal-body"><label class="field">Item name<input name="name" required maxlength="80" value="${esc(item?.name||'')}" placeholder="e.g. Masala dosa"></label><label class="field">Description<textarea name="description" maxlength="240" rows="2" placeholder="A short, appetising description">${esc(item?.description||'')}</textarea></label><label class="field">Category<input name="category" required maxlength="40" list="categories" value="${esc(item?.category||'')}" placeholder="e.g. Breakfast"><datalist id="categories">${[...new Set(state.items.map(i=>i.category))].map(c=>`<option value="${esc(c)}">`).join('')}</datalist></label><div class="field-row"><label class="field">Price (₹)<input name="price" type="number" min="0.01" max="100000" step="0.01" required value="${item?item.price_paise/100:''}" placeholder="0.00"></label><label class="field">Available stock<input name="stock" type="number" min="0" max="1000000" step="1" required value="${item?.stock??0}"></label></div>${item?`<label class="checkbox-field"><input type="checkbox" name="active" ${item.active?'checked':''}> Available on the menu</label>`:''}<p class="form-error" id="item-error" role="alert"></p></div><div class="modal-footer"><button type="button" class="btn btn-secondary" data-action="close-modal">Cancel</button><button type="submit" class="btn btn-primary">${icon('check')} ${item?'Save changes':'Add menu item'}</button></div></form>`);}
function receipt(order){if(!order)return;openModal(modalHeader('Order complete.','Good food is on its way.')+`<div class="modal-body receipt-body"><div class="receipt-check">${icon('check')}</div><p class="receipt-number">ORDER #${esc(order.id.slice(-6).toUpperCase())}</p><h3>${esc(order.customer_name)}</h3><div class="receipt-meta"><span>${shortDate(order.created_at)} · ${time(order.created_at)}</span><span>${esc(order.order_type)} · ${esc(order.payment_method)}</span>${order.is_demo?'<span class="sample-label">Sample transaction</span>':''}</div><div class="receipt-items">${(order.items||[]).map(i=>`<div class="summary-row"><span>${esc(i.item_name)} <span class="muted">× ${i.quantity}</span></span><strong>${money(i.unit_price_paise*i.quantity)}</strong></div>`).join('')}</div><div class="receipt-total"><span>Total paid</span><strong>${money(order.total_paise)}</strong></div><p class="receipt-thanks">Thanks for stopping by the campus kitchen.</p></div><div class="modal-footer"><button class="btn btn-secondary" data-action="print">${icon('print')} Print receipt</button><button class="btn btn-primary" data-action="close-modal">Done ${icon('check')}</button></div>`);}
function exportCsv(){const lines=inRange(state.lines,state.reportDays);if(!lines.length){toast('There are no sales to export in this period.',true);return;}const columns=['order_id','created_at','customer_name','order_type','payment_method','is_demo','item_id','item_name','quantity','unit_price_paise','line_total_paise'];const quote=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';const csv=[columns.join(','),...lines.map(l=>columns.map(c=>quote(l[c])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=`canteen-sales-${dateAgo(state.reportDays-1)}-to-${today()}.csv`;a.click();URL.revokeObjectURL(url);toast('Your sales report is ready.');}
function closeNav(){$('.app-shell').inert=false;$('.sidebar').classList.remove('open');$('.mobile-scrim').classList.remove('active');$('.mobile-menu').setAttribute('aria-expanded','false');}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=Number(el.dataset.id);if(action==='close-modal'){if(state.busy)return;$('#modal').close();}else if(action==='toggle-nav'){const open=$('.sidebar').classList.toggle('open');$('.mobile-scrim').classList.toggle('active',open);el.setAttribute('aria-expanded',String(open));$('.app-shell').inert=open;if(open)$('.sidebar .nav-close').focus();}else if(action==='close-nav'){closeNav();}else if(action==='category'){state.category=el.dataset.category;render();}else if(action==='add-cart'){const item=state.items.find(i=>i.id===id),quantity=state.cart.get(id)||0;if(!item||quantity>=item.stock){toast('There’s no more stock available for this item.',true);return;}state.cart.set(id,quantity+1);state.pending=null;render();}else if(action==='minus-cart'){const q=(state.cart.get(id)||0)-1;if(q>0)state.cart.set(id,q);else state.cart.delete(id);state.pending=null;render();}else if(action==='clear-cart'){state.cart.clear();state.pending=null;render();}else if(action==='checkout'){checkout();}else if(action==='new-item'){itemForm();}else if(action==='edit-item'){itemForm(id);}else if(action==='receipt'){receipt(state.orders.find(o=>o.id===el.dataset.id));}else if(action==='export'){exportCsv();}else if(action==='print'){window.print();}else if(action==='retry'){await loadWorkspace();}else if(action==='account-info'){showAccountInfo();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.sidebar').classList.contains('open')){closeNav();$('.mobile-menu').focus();return;}if(e.key==='Tab'&&$('.sidebar').classList.contains('open')){const focusable=[...$('.sidebar').querySelectorAll('a,button:not([disabled])')].filter(x=>x.offsetParent!==null);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}if((e.key==='Enter'||e.key===' ')&&e.target.matches('tr[data-action="receipt"]')){e.preventDefault();e.target.click();}});
document.addEventListener('input',e=>{if(e.target.id==='menu-search'||e.target.id==='inventory-search'){const id=e.target.id,pos=e.target.selectionStart;if(id==='menu-search')state.search=e.target.value;else state.inventorySearch=e.target.value;render();const input=$('#'+id);input.focus();if(input.type!=='search')input.setSelectionRange(pos,pos);}});
document.addEventListener('change',e=>{if(e.target.id==='chart-days'){state.chartDays=Number(e.target.value);render();}if(e.target.id==='report-days'){state.reportDays=Number(e.target.value);render();}});
document.addEventListener('submit',async e=>{if(!['checkout-form','item-form'].includes(e.target.id))return;e.preventDefault();if(state.busy)return;const form=e.target,fd=new FormData(form),button=$('[type="submit"]',form),original=button.innerHTML;state.busy=true;button.disabled=true;button.innerHTML='Saving…';try{if(form.id==='checkout-form'){const body={customer_name:String(fd.get('customer_name')).trim()||'Walk-in customer',order_type:fd.get('order_type'),payment_method:fd.get('payment_method'),items:[...state.cart].map(([item_id,quantity])=>({item_id,quantity}))};const signature=JSON.stringify(body);if(!state.pending||state.pending.signature!==signature)state.pending={signature,id:crypto.randomUUID()};const {order}=await api('/orders',{method:'POST',body:JSON.stringify({id:state.pending.id,...body})});state.cart.clear();state.pending=null;let refreshed=true;try{await refresh();}catch(error){if(!state.account||error.status===401||error.silent)return;refreshed=false;}render();receipt(order);toast(refreshed?'Order completed. Stock is up to date.':'Order completed and receipt saved. Refresh the page to update stock and sales.',!refreshed);}else{const id=form.dataset.id,item=state.items.find(i=>i.id===Number(id));const body={name:String(fd.get('name')).trim(),description:String(fd.get('description')).trim(),category:String(fd.get('category')).trim(),price_paise:Math.round(Number(fd.get('price'))*100),stock:Number(fd.get('stock')),image:item?.image||'',active:item?(fd.has('active')?1:0):1};await api('/menu'+(id?'/'+id:''),{method:id?'PATCH':'POST',body:JSON.stringify(body)});await refresh();$('#modal').close();render();toast(id?'Menu item updated. Ready for the next rush.':'A new favourite has joined the menu.');}}catch(error){if(!state.account||error.status===401||error.silent)return;const target=$(form.id==='checkout-form'?'#checkout-error':'#item-error');if(target)target.textContent=error.message;else toast(error.message,true);button.disabled=false;button.innerHTML=original;}finally{state.busy=false;}});
$('#modal').addEventListener('cancel',e=>{if(state.busy)e.preventDefault();});
window.addEventListener('hashchange',()=>{closeNav();if(!state.account){const page=location.hash.slice(1);if(['login','register','forgot-password'].includes(page)){state.authPage=page;state.authNotice='';state.resetChallenge=null;}renderAuth();}else render();window.scrollTo(0,0);});
document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
$('#today-date').innerHTML=icon('calendar')+new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',day:'numeric',month:'short',year:'numeric'}).format(new Date());
async function loadWorkspace(){const version=state.authVersion;try{await refresh();render();}catch(error){if(!state.account||version!==state.authVersion||error.silent)return;$('#main-content').innerHTML=`<div class="error-state">${icon('alert')}<h1>We couldn’t reach the kitchen.</h1><p>${esc(error.message)}</p><button class="btn btn-primary" data-action="retry">${icon('refresh')} Try again</button></div>`;}}

// Account state stays in memory. Session and recovery credentials are HTTP-only cookies.
function clearAccount(){
  state.authVersion+=1;state.account=null;state.items=[];state.orders=[];state.lines=[];
  state.cart.clear();state.pending=null;state.search='';state.inventorySearch='';state.category='All items';state.busy=false;
  state.resetChallenge=null;state.recoveryMobile='';state.authPage='login';state.authNotice='';state.authBusy=false;
  clearInterval(state.recoveryTimer);closeNav();$('#modal').close();$('#modal-content').innerHTML='';$('#main-content').innerHTML='';
  $('#operator-name').textContent='Canteen owner';$('#workspace-name').textContent='Your canteen';
  document.querySelectorAll('.operator-avatar,.topbar .avatar').forEach(e=>e.textContent='CM');
  $('#toast').classList.remove('visible');document.body.classList.remove('authenticated','auth-pending');
}
function updateAccountDisplay(){
  const a=state.account;if(!a)return;
  $('#operator-name').textContent=a.owner_name;$('#workspace-name').textContent=a.canteen_name;
  const initials=a.owner_name.trim().split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase();
  document.querySelectorAll('.operator-avatar,.topbar .avatar').forEach(e=>{e.textContent=initials;e.setAttribute('aria-label',a.owner_name);});
}
function showAccountInfo(){const a=state.account;if(!a)return;openModal(modalHeader('Your canteen account','Details for this workspace.')+`<div class="modal-body account-details"><dl><div><dt>Canteen</dt><dd>${esc(a.canteen_name)}</dd></div><div><dt>Owner</dt><dd>${esc(a.owner_name)}</dd></div><div><dt>Mobile number</dt><dd>+91 ${esc(a.mobile)}</dd></div><div><dt>GSTIN</dt><dd>${esc(a.gst_number)}</dd></div></dl><p class="form-note">Your menu, stock and sales belong to this account. GST number length is checked; government registration status is not verified.</p></div><div class="modal-footer"><button class="btn btn-primary" data-action="close-modal">Done</button></div>`);}
function accountBrand(){return `<a class="auth-brand" href="#login" aria-label="virudhigakv sign in"><span class="auth-brand-symbol">${icon('utensils')}</span><span>virudhigakv</span></a>`;}
function passwordInput(name,label,autocomplete='new-password',confirm=false){return `<label class="auth-field" for="auth-${name}">${label}<span class="password-field"><input id="auth-${name}" name="${name}" type="password" required minlength="8" maxlength="128" autocomplete="${autocomplete}" ${confirm?'':'aria-describedby="password-help"'}><button class="password-toggle" type="button" data-auth-action="toggle-password" data-target="auth-${name}" aria-label="Show ${label.toLowerCase()}" aria-pressed="false">${icon('eye')}<span>Show</span></button></span></label>`;}
function mobileInput(value='',autocomplete='tel-national'){return `<label class="auth-field" for="auth-mobile">Mobile number<span class="mobile-input"><span aria-hidden="true">+91</span><input id="auth-mobile" name="mobile" type="tel" inputmode="numeric" autocomplete="${autocomplete}" required minlength="10" maxlength="10" placeholder="9876543210" value="${esc(value)}" aria-describedby="mobile-help auth-mobile-error"></span><small id="mobile-help">Enter any 10-digit number for this demo, without +91.</small><span id="auth-mobile-error" class="auth-field-error" aria-live="polite"></span></label>`;}
function authStatus(){return `<div class="auth-message ${state.authNotice?'visible':''}" id="auth-message" role="status">${esc(state.authNotice)}</div><p class="auth-error" id="auth-error" role="alert" tabindex="-1"></p>`;}
function recoveryDescription(){return state.recoveryMode==='demo'?`<div class="recovery-notice">${icon('info')}<p><strong>Demo verification</strong><br>No SMS will be sent. A demo code will appear here in a browser where you previously created or signed in to this account.</p></div>`:!state.smsAvailable?`<div class="recovery-notice recovery-unavailable">${icon('info')}<p>SMS password recovery isn’t configured yet. Please contact your canteen administrator.</p></div>`:`<p class="auth-intro">We’ll send a 6-digit verification code to your registered mobile number.</p>`;}
function renderAuth(){
  clearInterval(state.recoveryTimer);document.body.classList.remove('authenticated','auth-pending');
  const page=state.authPage;let content='';
  if(page==='register'){
    document.title='Create account — virudhigakv';
    content=`<a class="auth-back" href="#login">${icon('arrow')} Back to sign in</a><div class="auth-eyebrow">A FRESH START</div><h1>Your canteen starts here.</h1><p class="auth-intro">A few details, and you’re ready for the next rush.</p><form id="auth-register" class="auth-form" novalidate>${authStatus()}<div class="auth-two-col"><label class="auth-field" for="auth-canteen">Canteen name<input id="auth-canteen" name="canteen_name" required minlength="2" maxlength="100" autocomplete="organization" placeholder="e.g. Greenleaf Canteen"></label><label class="auth-field" for="auth-owner">Owner name<input id="auth-owner" name="owner_name" required minlength="2" maxlength="100" autocomplete="name" placeholder="Your full name"></label></div>${mobileInput()}<label class="auth-field" for="auth-gst">GST number (GSTIN)<input id="auth-gst" class="gst-input" name="gst_number" required minlength="15" maxlength="15" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="15-character GSTIN" aria-describedby="gst-help auth-gst-error"><small id="gst-help">Enter exactly 15 letters or digits. Demo values are accepted.</small><span id="auth-gst-error" class="auth-field-error" aria-live="polite"></span></label><div class="auth-two-col">${passwordInput('password','Password')}${passwordInput('confirm_password','Confirm password','new-password',true)}</div><p id="password-help" class="password-help">Use 8–128 characters. A long, unique password works best.</p><button class="auth-submit" type="submit">Create account ${icon('arrow')}</button><p class="auth-switch">Already have an account? <a href="#login">Sign in</a></p></form>`;
  }else if(page==='forgot-password'){
    document.title='Recover password — virudhigakv';
    content=`<a class="auth-back" href="#login">${icon('arrow')} Back to sign in</a><div class="auth-eyebrow">LET’S GET YOU BACK IN</div><h1>Forgot your password?</h1>${recoveryDescription()}<form id="auth-forgot" class="auth-form" novalidate>${authStatus()}${mobileInput(state.recoveryMobile||'')}<button class="auth-submit" type="submit" ${state.recoveryMode!=='demo'&&!state.smsAvailable?'disabled':''}>${state.recoveryMode==='demo'?'Get demo code':'Send verification code'} ${icon('arrow')}</button><p class="auth-switch">Remember it now? <a href="#login">Sign in</a></p></form>`;
  }else if(page==='reset-password'&&state.resetChallenge){
    document.title='Verify & reset password — virudhigakv';const c=state.resetChallenge;const masked='••••••'+c.mobile.slice(-4);
    content=`<button class="auth-back" type="button" data-auth-action="change-mobile">${icon('arrow')} Change mobile number</button><div class="auth-eyebrow">YOUR NEXT CHAPTER</div><h1>Set a fresh password.</h1><p class="auth-intro">Enter the 6-digit code for <strong>+91 ${esc(masked)}</strong>, then choose your new password.</p><form id="auth-reset" class="auth-form" novalidate>${authStatus()}<label class="auth-field" for="auth-otp">Verification code<input id="auth-otp" name="otp" class="otp-input" inputmode="numeric" type="text" required minlength="6" maxlength="6" pattern="[0-9]{6}" autocomplete="one-time-code" placeholder="000000" aria-describedby="otp-help"><small id="otp-help">The code expires in ${Math.max(1,Math.ceil(c.expiresIn/60))} minutes. You have up to 5 verification attempts.</small></label>${passwordInput('password','New password')}${passwordInput('confirm_password','Confirm new password','new-password',true)}<p id="password-help" class="password-help">Use 8–128 characters. Your other sessions will be signed out.</p><button class="auth-submit" type="submit">Verify & reset password ${icon('arrow')}</button><div class="resend-row"><span>Need another code?</span><button type="button" class="auth-inline-button" data-auth-action="resend-code" id="resend-code">Resend code</button></div></form>${c.demo?`<div class="demo-code-panel" role="status"><span class="demo-code-label">DEMO ONLY · NO SMS WAS SENT</span><p>Enter this code in the verification field above.</p><strong class="demo-code" aria-label="Demo verification code ${esc(c.demoOtp.split('').join(' '))}">${esc(c.demoOtp)}</strong></div>`:''}`;
  }else{
    state.authPage='login';document.title='Sign in — virudhigakv';
    content=`<div class="auth-eyebrow">WELCOME TO YOUR KITCHEN</div><h1>Good to have you back.</h1><p class="auth-intro">Sign in to keep your canteen running smoothly.</p><form id="auth-login" class="auth-form" novalidate>${authStatus()}${mobileInput(state.recoveryMobile||'','username')}${passwordInput('password','Password','current-password')}<span id="password-help" class="sr-only">Enter your account password.</span><div class="auth-forgot-link"><a href="#forgot-password">Forgot password?</a></div><button class="auth-submit" type="submit">Sign in ${icon('arrow')}</button><div class="auth-separator"><span>New to canteen?</span></div><a class="auth-create-link" href="#register">Create an account ${icon('plus')}</a></form>`;
  }
  $('#auth-root').innerHTML=`<div class="auth-layout"><aside class="auth-story">${accountBrand()}<div class="auth-story-content"><span class="story-kicker">MADE FOR EVERYDAY HUNGER</span><h2>Good food.<br>Great days.<br><em>Your canteen.</em></h2><p>From the first cup of chai to the last plate of the day. A simpler way to manage it all.</p><div class="auth-story-illustration" aria-hidden="true"><span class="auth-plate"><span></span><i></i><b></b></span><span class="auth-cup"></span><span class="auth-fork"></span></div><div class="story-points"><span>${icon('bag')} Effortless orders</span><span>${icon('box')} Stock in check</span><span>${icon('chart')} Clearer insights</span></div></div><p class="auth-story-footer">A little clarity for a busy kitchen.</p></aside><main class="auth-main" id="account-content"><div class="auth-mobile-brand">${accountBrand()}</div><section class="auth-card ${page==='register'?'auth-card-register':''}" aria-label="${page==='register'?'Create canteen account':page==='login'?'Sign in':'Password recovery'}">${content}</section><p class="auth-footer">Your canteen. Your workspace. <span>Made for the daily rush.</span></p></main></div>`;
  $('.skip-link').href='#account-content';
  if(page==='reset-password'&&state.resetChallenge){updateResendButton();state.recoveryTimer=setInterval(updateResendButton,1000);}
}
function updateResendButton(){const button=$('#resend-code'),c=state.resetChallenge;if(!button||!c){clearInterval(state.recoveryTimer);return;}const wait=Math.max(0,Math.ceil((c.resendAt-Date.now())/1000));button.disabled=state.authBusy||wait>0;button.textContent=wait?`Resend in ${wait}s`:'Resend code';}
function authError(message,fieldId=''){const input=fieldId?$('#'+fieldId):null,inline=fieldId?$('#'+fieldId+'-error'):null,box=$('#auth-error');if(inline)inline.textContent=message;if(box)box.textContent=inline?'':message;if(input){input.setAttribute('aria-invalid','true');input.focus();}else if(box)box.focus();}
function normalizeMobile(value){return String(value).replace(/\s+/g,'').replace(/^\+91/,'');}
function validMobile(mobile){return /^\d{10}$/.test(mobile);}
function validGstin(value){return /^[A-Z0-9]{15}$/.test(value);}
function acceptChallenge(result,mobile){state.recoveryMobile=mobile;state.resetChallenge={id:result.challenge_id,mobile,expiresIn:result.expires_in||600,resendAt:Date.now()+(result.resend_after||60)*1000,demo:result.demo===true,demoOtp:String(result.demo_otp||'')};state.authNotice=result.message||'If an account exists, a verification code will be sent.';state.authPage='reset-password';renderAuth();$('#auth-otp')?.focus();}
async function enterWorkspace(account){state.account=account;state.authVersion+=1;state.authNotice='';state.resetChallenge=null;clearInterval(state.recoveryTimer);updateAccountDisplay();document.body.classList.remove('auth-pending');document.body.classList.add('authenticated');$('#auth-root').innerHTML='';$('.skip-link').href='#main-content';history.replaceState(null,'','#overview');$('#main-content').innerHTML='<div class="loading-state"><div class="loader"></div><h2>Getting your kitchen ready…</h2><p>Loading your menu and sales.</p></div>';await loadWorkspace();}
async function logout(){if(state.authBusy)return;if(state.busy){toast('Please wait for the current change to finish, then log out.',true);return;}state.authBusy=true;document.querySelectorAll('[data-action="logout"]').forEach(b=>b.disabled=true);try{await api('/auth/logout',{method:'POST',body:'{}'});clearAccount();state.authNotice='You’ve been signed out. See you at the next rush.';history.replaceState(null,'','#login');renderAuth();}catch(error){toast('Could not sign out. '+error.message,true);}finally{state.authBusy=false;document.querySelectorAll('[data-action="logout"]').forEach(b=>b.disabled=false);}}
document.addEventListener('click',async event=>{
 if(event.target.closest('[data-nav]')&&$('.sidebar').classList.contains('open'))closeNav();
 const logoutButton=event.target.closest('[data-action="logout"]');if(logoutButton){await logout();return;}
 const button=event.target.closest('[data-auth-action]');if(!button)return;
 if(button.dataset.authAction==='toggle-password'){const input=$('#'+button.dataset.target);const show=input.type==='password';input.type=show?'text':'password';button.setAttribute('aria-pressed',String(show));button.setAttribute('aria-label',(show?'Hide ':'Show ')+(input.name.includes('confirm')?'confirmation password':'password'));$('span',button).textContent=show?'Hide':'Show';}
 if(button.dataset.authAction==='change-mobile'&&!state.authBusy){state.authPage='forgot-password';state.authNotice='';state.resetChallenge=null;renderAuth();}
 if(button.dataset.authAction==='resend-code'&&!state.authBusy&&state.resetChallenge){state.authBusy=true;button.disabled=true;try{const result=await api('/auth/forgot-password',{method:'POST',body:JSON.stringify({mobile:state.resetChallenge.mobile})});acceptChallenge(result,state.resetChallenge.mobile);}catch(error){authError(error.message);}finally{state.authBusy=false;updateResendButton();}}
});
document.addEventListener('input',event=>{if(event.target.closest('.auth-form')){event.target.removeAttribute('aria-invalid');const inline=$('#'+event.target.id+'-error');if(inline)inline.textContent='';}if(event.target.id==='auth-gst')event.target.value=event.target.value.toUpperCase();if(event.target.id==='auth-mobile')event.target.value=event.target.value.replace(/[^0-9]/g,'').slice(0,10);if(event.target.id==='auth-otp')event.target.value=event.target.value.replace(/[^0-9]/g,'').slice(0,6);});
document.addEventListener('submit',async event=>{
 const form=event.target;if(!/^auth-(login|register|forgot|reset)$/.test(form.id))return;event.preventDefault();if(state.authBusy)return;
 form.querySelectorAll('.auth-field-error').forEach(e=>e.textContent='');form.querySelectorAll('[aria-invalid]').forEach(e=>e.removeAttribute('aria-invalid'));const fd=new FormData(form),kind=form.id.slice(5),mobile=normalizeMobile(fd.get('mobile')||state.resetChallenge?.mobile||'');
 if(!validMobile(mobile)){authError('Enter exactly 10 digits, for example 1234567890.','auth-mobile');return;}
 const password=String(fd.get('password')||'');
 if(kind==='register'||kind==='reset'){
   if(password.length<8||password.length>128){authError('Use a password between 8 and 128 characters.');return;}
   if(password!==fd.get('confirm_password')){authError('The passwords don’t match. Please enter the same password in both fields.');return;}
 }
 let body={mobile};
 if(kind==='login')body={mobile,password};
 if(kind==='register'){
   const canteen_name=String(fd.get('canteen_name')).trim(),owner_name=String(fd.get('owner_name')).trim(),gst_number=String(fd.get('gst_number')).trim().toUpperCase();
   if(canteen_name.length<2||owner_name.length<2){authError('Canteen and owner names need at least 2 characters.');return;}
   if(!validGstin(gst_number)){authError('Enter exactly 15 letters or digits, for example 1234567890OKJHG.','auth-gst');return;}
   body={canteen_name,owner_name,mobile,gst_number,password};
 }
 if(kind==='reset'){if(!state.resetChallenge){authError('Request a new verification code to continue.');return;}const otp=String(fd.get('otp'));if(!/^\d{6}$/.test(otp)){authError('Enter the 6-digit verification code.');return;}body={challenge_id:state.resetChallenge.id,mobile,otp,password};}
 state.authBusy=true;const submit=$('[type="submit"]',form),label=submit.innerHTML;submit.disabled=true;submit.innerHTML=`<span class="button-spinner"></span>${kind==='forgot'?'Requesting code…':kind==='reset'?'Verifying…':kind==='register'?'Creating account…':'Signing in…'}`;$('#auth-error').textContent='';
 try{
   const endpoint={login:'login',register:'register',forgot:'forgot-password',reset:'reset-password'}[kind];const result=await api('/auth/'+endpoint,{method:'POST',body:JSON.stringify(body)});
   if(kind==='login'||kind==='register'){form.reset();await enterWorkspace(result.account);}
   else if(kind==='forgot')acceptChallenge(result,mobile);
   else{form.reset();state.resetChallenge=null;state.authPage='login';state.authNotice=result.message||'Password updated. Sign in with your new password.';state.recoveryMobile=mobile;history.replaceState(null,'','#login');renderAuth();}
 }catch(error){authError(error.message);}finally{state.authBusy=false;if(submit.isConnected){submit.disabled=false;submit.innerHTML=label;}updateResendButton();}
});
async function start(){
 try{const session=await api('/auth/session');state.smsAvailable=session.sms_available===true;state.recoveryMode=session.recovery_mode||'sms';if(session.account){await enterWorkspace(session.account);}else{const page=location.hash.slice(1);state.authPage=['login','register','forgot-password'].includes(page)?page:'login';renderAuth();}}
 catch(error){document.body.classList.remove('authenticated','auth-pending');$('#auth-root').innerHTML=`<main class="auth-connection-error">${accountBrand()}<div class="error-state">${icon('alert')}<h1>We couldn’t open your canteen.</h1><p>${esc(error.message)}</p><button class="auth-submit" id="retry-account">Try again ${icon('refresh')}</button></div></main>`;$('#retry-account').addEventListener('click',start);}
}
window.addEventListener('pageshow',event=>{if(event.persisted){clearAccount();start();}});
start();
window.addEventListener('resize',()=>{if(window.innerWidth>900&&$('.sidebar').classList.contains('open'))closeNav();});
